-- =====================================================
-- REMOÇÃO DAS TABELAS (ordem reversa por causa das FKs)
-- =====================================================
DROP TABLE IF EXISTS avaliacoes CASCADE;
DROP TABLE IF EXISTS pagamentos CASCADE;
DROP TABLE IF EXISTS itens_pedido CASCADE;
DROP TABLE IF EXISTS pedidos CASCADE;
DROP TABLE IF EXISTS clientes CASCADE;
DROP TABLE IF EXISTS produtos CASCADE;
DROP TABLE IF EXISTS categorias CASCADE;

-- =====================================================
-- CRIAÇÃO DAS TABELAS (DDL)
-- =====================================================

CREATE TABLE IF NOT EXISTS categorias (
    categoria_id SERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    descricao TEXT,
    ativo BOOLEAN DEFAULT TRUE,
    data_criacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS produtos (
    produto_id SERIAL PRIMARY KEY,
    nome VARCHAR(200) NOT NULL,
    categoria_id INTEGER REFERENCES categorias(categoria_id),
    preco NUMERIC(10,2) NOT NULL,
    estoque INTEGER DEFAULT 0,
    marca VARCHAR(100),
    descricao TEXT,
    ativo BOOLEAN DEFAULT TRUE,
    data_criacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS clientes (
    cliente_id SERIAL PRIMARY KEY,
    nome VARCHAR(150) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    cpf VARCHAR(14) UNIQUE,
    telefone VARCHAR(20),
    data_nascimento DATE,
    cidade VARCHAR(100),
    estado CHAR(2),
    cep VARCHAR(10),
    ativo BOOLEAN DEFAULT TRUE,
    data_cadastro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS pedidos (
    pedido_id SERIAL PRIMARY KEY,
    cliente_id INTEGER REFERENCES clientes(cliente_id),
    data_pedido TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(20) DEFAULT 'pendente',
    valor_total NUMERIC(12,2),
    frete NUMERIC(10,2) DEFAULT 0,
    desconto NUMERIC(10,2) DEFAULT 0,
    data_entrega_prevista DATE,
    data_entrega_realizada DATE
);

CREATE TABLE IF NOT EXISTS itens_pedido (
    item_pedido_id SERIAL PRIMARY KEY,
    pedido_id INTEGER REFERENCES pedidos(pedido_id),
    produto_id INTEGER REFERENCES produtos(produto_id),
    quantidade INTEGER NOT NULL,
    preco_unitario NUMERIC(10,2) NOT NULL
);

CREATE TABLE IF NOT EXISTS pagamentos (
    pagamento_id SERIAL PRIMARY KEY,
    pedido_id INTEGER REFERENCES pedidos(pedido_id),
    metodo VARCHAR(50) NOT NULL,
    status VARCHAR(20) DEFAULT 'pendente',
    valor NUMERIC(12,2) NOT NULL,
    data_pagamento TIMESTAMP
);

CREATE TABLE IF NOT EXISTS avaliacoes (
    avaliacao_id SERIAL PRIMARY KEY,
    produto_id INTEGER REFERENCES produtos(produto_id),
    cliente_id INTEGER REFERENCES clientes(cliente_id),
    nota INTEGER CHECK (nota >= 1 AND nota <= 5),
    comentario TEXT,
    util_count INTEGER DEFAULT 0,
    data_avaliacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(produto_id, cliente_id)
);

-- =====================================================
-- LIMPEZA DAS TABELAS (ordem reversa por causa das FKs)
-- =====================================================
TRUNCATE TABLE avaliacoes CASCADE;
TRUNCATE TABLE pagamentos CASCADE;
TRUNCATE TABLE itens_pedido CASCADE;
TRUNCATE TABLE pedidos CASCADE;
TRUNCATE TABLE clientes CASCADE;
TRUNCATE TABLE produtos CASCADE;
TRUNCATE TABLE categorias CASCADE;

